const fs = require('fs');
const path = require('path');

const htmlPath = path.join(__dirname, 'index.html');
const expectedIds = ['note-input', 'save-btn', 'notes-list'];

try {
    const content = fs.readFileSync(htmlPath, 'utf8');
    let allFound = true;

    expectedIds.forEach(id => {
        if (!content.includes(`id="${id}"`)) {
            console.error(`Missing ID: ${id}`);
            allFound = false;
        }
    });

    if (allFound) {
        console.log('Smoke check passed: All expected IDs found in index.html');
        process.exit(0);
    } else {
        console.error('Smoke check failed: Some IDs are missing');
        process.exit(1);
    }
} catch (err) {
    console.error('Error reading index.html:', err);
    process.exit(1);
}
